/*
 * mod-unbound: the Heroic Quartermaster (ROADMAP.md "Heroic currency and vendor").
 *
 * Creature 190104 (data/sql/db-world/unbound_heroic_quartermaster.sql) sells the heroic dungeon gear for Heroic
 * Sigils. A 3.3.5 vendor window holds at most 150 items and there are 450 heroic items, so talking to it shows a menu
 * of pages; each page opens the vendor list of a never-spawned page creature (190105-190109, their npc_vendor rows
 * generated by tools/heroic_loot.py, QUARTERMASTER_PAGES). WorldSession::SendListInventory takes the page's entry and
 * remembers it as the current vendor, so buying (and the 2-hour refund) uses that page's list.
 */

#include "Creature.h"
#include "Player.h"
#include "ScriptMgr.h"
#include "ScriptedGossip.h"
#include "WorldSession.h"

#include <utility>

namespace
{
    constexpr uint32 QUARTERMASTER_TEXT = 190104;  // npc_text greeting

    // vendor entry -> menu text; keep in sync with QUARTERMASTER_PAGES in tools/heroic_loot.py
    std::pair<uint32, char const*> const PAGES[] = {
        { 190105, "Rings, necks, cloaks, wrists and belts (10 Sigils)" },
        { 190106, "Head, shoulders and chest (15 Sigils)" },
        { 190107, "Hands, legs and feet (15 Sigils)" },
        { 190108, "Weapons, shields and off-hands (20-25 Sigils)" },
        { 190109, "Final boss treasures (30 Sigils)" },
    };
}

class npc_unbound_heroic_quartermaster : public CreatureScript
{
public:
    npc_unbound_heroic_quartermaster() : CreatureScript("npc_unbound_heroic_quartermaster") { }

    bool OnGossipHello(Player* player, Creature* creature) override
    {
        ClearGossipMenuFor(player);
        for (auto const& [entry, text] : PAGES)
            AddGossipItemFor(player, GOSSIP_ICON_VENDOR, text, GOSSIP_SENDER_MAIN, entry);
        SendGossipMenuFor(player, QUARTERMASTER_TEXT, creature->GetGUID());
        return true;
    }

    bool OnGossipSelect(Player* player, Creature* creature, uint32 /*sender*/, uint32 action) override
    {
        CloseGossipMenuFor(player);
        for (auto const& [entry, text] : PAGES)
            if (entry == action)
                player->GetSession()->SendListInventory(creature->GetGUID(), entry);
        return true;
    }
};

void AddSC_unbound_heroic_quartermaster()
{
    new npc_unbound_heroic_quartermaster();
}
